import { describe, expect, it } from "vitest";
import { screen } from "@testing-library/react";
import {
  addRecord, chooseFilter, editRecord, expectNoRow, expectRow, reload,
  removeRecord, renderApp, rowTitles, runAction, stat,
} from "./test/helpers.js";

describe("journeys", () => {
  it("adds a book and shows it in the list", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Audi", Category: "Novel" });
    expectRow("Alpha", "Audi", "Novel");
  });

  it("rejects an empty required field", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "", Author: "Audi", Category: "Novel" });
    expect(screen.getByText("Title: Title is required")).toBeVisible();
    expect(rowTitles()).toEqual([]);
  });

  it("edits an existing book", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Audi", Category: "Novel" });
    await editRecord(user, "Alpha", { Title: "Alpha II" });
    expectRow("Alpha II");
    expectNoRow("Alpha");
  });

  it("deletes a book added by mistake", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Audi", Category: "Novel" });
    await removeRecord(user, "Alpha");
    expectNoRow("Alpha");
  });

  it("lends a book and shows the borrower", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Audi", Category: "Novel" });
    await runAction(user, "Lend", "Alpha", "Sam");
    expectRow("Alpha", "Lent to Sam");
  });

  it("returns a book and clears the borrower", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Audi", Category: "Novel" });
    await runAction(user, "Lend", "Alpha", "Sam");
    await runAction(user, "Return", "Alpha");
    expect(row("Alpha").textContent).not.toContain("Lent to Sam");
  });

  it("filters to books currently lent out", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Audi", Category: "Novel" });
    await addRecord(user, { Title: "Beta", Author: "Bee", Category: "Novel" });
    await runAction(user, "Lend", "Alpha", "Sam");
    await chooseFilter(user, "Lent out");
    expect(rowTitles()).toEqual(["Alpha"]);
  });

  it("filters books by category", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Audi", Category: "Novel" });
    await addRecord(user, { Title: "Beta", Author: "Bee", Category: "Cookbook" });
    await chooseFilter(user, "Novel");
    expect(rowTitles()).toEqual(["Alpha"]);
  });

  it("shows how many books are lent out", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Audi", Category: "Novel" });
    await runAction(user, "Lend", "Alpha", "Sam");
    expect(stat("Lent out")).toBe("1");
  });

  it("preserves data across a browser refresh", async () => {
    const { user } = renderApp();
    await addRecord(user, { Title: "Alpha", Author: "Audi", Category: "Novel" });
    await runAction(user, "Lend", "Alpha", "Sam");
    reload();
    expectRow("Alpha", "Lent to Sam");
    expect(stat("Lent out")).toBe("1");
  });
});

